  [Fact] public void Diag() {
    var groups = new Dictionary<string,int>();
    foreach (var j in JammedValues) foreach (var a in Amounts) foreach (var s in Stocks) {
      var e = ExpectedWithdraw(250,0,s,j,a); var (r,d) = Withdraw(250,0,s,j,a);
      bool ok = e.Result==r && e.StockAfter==d.Stock;
      var notes = e.Result.Notes;
      string key;
      if (!ok) key = $"KO total>4={notes.Total>4} fifties={notes.Fifties>0} twenties={notes.Twenties>0} tens={notes.Tens>0}";
      else if (notes.Total>4) key = $"OK>4 f={notes.Fifties} t={notes.Twenties} n={notes.Tens} jam={j}";
      else continue;
      groups[key] = groups.GetValueOrDefault(key)+1;
    }
    throw new Exception(string.Join("\n", groups.OrderBy(k=>k.Key).Select(k=>k.Key+" : "+k.Value)));
  }
}
EOF
dotnet test --filter ZzDiag 2>&1 | sed -n '/Error Message/,/Stack Trace/p' | head -80; rm Atm.Tests/ZzDiag.cs

